/* @lc app=leetcode id=1899 lang=kotlin */
class Solution{fun mergeTriplets(triplets:Array<IntArray>,target:IntArray):Boolean=triplets.filter{it[0]<=target[0]&&it[1]<=target[1]&&it[2]<=target[2]}.fold(intArrayOf(0,0,0)){acc,t->acc.apply{this[0]=maxOf(this[0],t[0])}.also{it[1]=maxOf(it[1],t[1])}.also{it[2]=maxOf(it[2],t[2])}}.contentEquals(target)}